// Cleanup: delete the created record
const baseurl = pm.collectionVariables.get("baseurl") || pm.environment.get("baseurl") || pm.globals.get("baseurl");
const json = pm.response.json();
const id = json.id || json.Id || json.ID;

if (id) {
    pm.sendRequest({
        url: baseurl + "/api/musicrecords/" + id,
        method: "DELETE"
    }, function (err, res) {
        if (err) {
            console.error("Cleanup DELETE failed:", err);
        } else {
            console.log("Cleanup: deleted record with id:", id, "status:", res.code);
        }
    });
} else {
    console.warn("Cleanup: could not find id in response, skipping DELETE");
}

